//
//  DS4ToolSyntax.swift
//  ZenCODE
//
//  Native tool-call syntaxes spoken by the model families served by the
//  in-process DS4 engine. Markers mirror ds4_agent.c (agent_tool_start,
//  agent_dsml_tag_name, agent_dsml_param_close and the syntax reminders) and the
//  replay format mirrors ds4_server.c (append_*_tool_calls_text).
//

import Foundation

/// The tool-call syntax natively generated by a DS4 model family.
///
/// The raw value is the `engine_tool_syntax` id exposed by the C engine ABI.
enum DS4ToolSyntax: Int32, Sendable, CaseIterable {
    /// DeepSeek V3.2/V4 DSML: `<｜DSML｜tool_calls>` / `<｜DSML｜invoke name="…">`.
    case dsml = 0
    /// DeepSeek 4.1 DSML: the same grammar with spaced tag names
    /// (`<｜DSML｜ calls>`, `<｜DSML｜ invoke …>`, `<｜DSML｜ parameter …>`).
    case dsml41 = 1
    /// GLM: `<tool_call>name<arg_key>k</arg_key><arg_value>v</arg_value>…</tool_call>`.
    case glm = 2
    /// Qwen: `<tool_call>\n<function=name>\n<parameter=k>\nv\n</parameter>\n</function>\n</tool_call>`.
    case qwen = 3
}

extension DS4ToolSyntax {
    /// Whether an assistant turn is terminated by the EOS token in the
    /// transcript. GLM ends its turns with the next role marker instead
    /// (`agent_tool_syntax_assistant_turn_uses_eos`).
    var assistantTurnUsesEOS: Bool {
        self != .glm
    }

    /// GLM and Qwen both open a call with `<tool_call>` and render tool results
    /// as chat messages (`agent_syntax_is_xml_tool_call`).
    var usesXMLToolCall: Bool {
        self == .glm || self == .qwen
    }

    /// DeepSeek DSML family (`dsml` and `dsml41`).
    var usesDSML: Bool {
        !usesXMLToolCall
    }

    /// The canonical marker that opens a tool-call block (`agent_tool_start`).
    var toolCallOpenMarker: String {
        switch self {
        case .dsml:
            "<｜DSML｜tool_calls>"
        case .dsml41:
            "<｜DSML｜ calls>"
        case .glm, .qwen:
            "<tool_call>"
        }
    }

    /// The marker that closes one string argument value; the only delimiter
    /// escaped inside argument bodies (`ds4_tool_text.h`).
    var parameterCloseMarker: String {
        switch self {
        case .dsml:
            "</｜DSML｜parameter>"
        case .dsml41:
            "</｜DSML｜ parameter>"
        case .glm:
            "</arg_value>"
        case .qwen:
            "</parameter>"
        }
    }

    /// Short family name used in ds4-agent diagnostics
    /// (`incomplete DSML tool call`, `invalid GLM tool call`, …).
    var displayName: String {
        switch self {
        case .dsml, .dsml41:
            "DSML"
        case .glm:
            "GLM"
        case .qwen:
            "Qwen"
        }
    }

    /// The syntax reminder ds4-agent appends to a malformed-tool-call error
    /// observation (`agent_*_syntax_reminder`).
    var syntaxReminder: String {
        switch self {
        case .dsml:
            """
            DSML syntax reminder:
            <｜DSML｜tool_calls>
            <｜DSML｜invoke name="$TOOL_NAME">
            <｜DSML｜parameter name="$PARAMETER_NAME" string="true|false">$PARAMETER_VALUE</｜DSML｜parameter>
            </｜DSML｜invoke>
            </｜DSML｜tool_calls>

            """
        case .dsml41:
            """
            DSML syntax reminder:
            <｜DSML｜ calls>
            <｜DSML｜ invoke name="$TOOL_NAME">
            <｜DSML｜ parameter name="$PARAMETER_NAME" string="true|false">$PARAMETER_VALUE</｜DSML｜ parameter>
            </｜DSML｜ invoke>
            </｜DSML｜ calls>

            """
        case .glm:
            """
            GLM tool-call syntax reminder:
            <tool_call>$TOOL_NAME<arg_key>$PARAMETER_NAME</arg_key><arg_value>$PARAMETER_VALUE</arg_value></tool_call>

            """
        case .qwen:
            """
            Tool-call syntax reminder:
            <tool_call>
            <function=$TOOL_NAME>
            <parameter=$PARAMETER_NAME>
            $PARAMETER_VALUE
            </parameter>
            </function>
            </tool_call>

            """
        }
    }

    /// Whether generated output starts inside a reasoning span, given the think
    /// mode used for `ds4_chat_append_assistant_prefix` (ds4.c).
    ///
    /// For every family the answer is the think mode itself:
    /// - `dsml`/`dsml41`: the prefix is `<｜Assistant｜><think>` with thinking
    ///   enabled, `<｜Assistant｜></think>` otherwise;
    /// - `glm`: `<|assistant|><think>` with thinking enabled,
    ///   `<|assistant|><think></think>` otherwise;
    /// - `qwen`: `<|im_start|>assistant\n<think>\n` with thinking enabled,
    ///   `<|im_start|>assistant\n<think>\n\n</think>\n\n` otherwise.
    ///
    /// ds4-agent initializes its stream renderer the same way
    /// (`in_think = ds4_think_mode_enabled(think_mode)`). Pass the result as
    /// `DS4GeneratedOutputParser(startsInsideThinking:)`.
    func outputStartsInsideThinking(thinkModeEnabled: Bool) -> Bool {
        thinkModeEnabled
    }

    // MARK: - DSML tag spelling

    static let dsmlBar = "｜"

    /// `agent_dsml_tag_name`: DSML 4.1 spells the tag names with a leading space
    /// and renames `tool_calls` to `calls`.
    func dsmlTagName(_ tag: DS4DSMLTag) -> String {
        switch (self, tag) {
        case (.dsml41, .toolCalls):
            " calls"
        case (.dsml41, .invoke):
            " invoke"
        case (.dsml41, .parameter):
            " parameter"
        case (_, .toolCalls):
            "tool_calls"
        case (_, .invoke):
            "invoke"
        case (_, .parameter):
            "parameter"
        }
    }

    func dsmlOpenTag(_ tag: DS4DSMLTag) -> String {
        "<｜DSML｜" + dsmlTagName(tag)
    }

    func dsmlCloseTag(_ tag: DS4DSMLTag) -> String {
        "</｜DSML｜" + dsmlTagName(tag) + ">"
    }
}

/// The three DSML tags.
enum DS4DSMLTag: Sendable, CaseIterable {
    case toolCalls
    case invoke
    case parameter
}

/// One assistant tool call to replay in the rendered transcript.
struct DS4ToolCallReplay: Sendable, Equatable, Hashable {
    let name: String
    /// A JSON object. Its top-level key order is preserved by the renderer.
    let argumentsJSON: String

    init(name: String, argumentsJSON: String) {
        self.name = name
        self.argumentsJSON = argumentsJSON
    }

    init(_ call: DirectAgentToolCall) {
        self.init(name: call.name, argumentsJSON: call.argumentsJSON)
    }
}

/// Malformed tool-call output. `detail` follows the ds4-agent diagnostics
/// (`expected <arg_value> in GLM tool call`, `incomplete DSML tool call`, …).
struct DS4ToolParseError: Error, Sendable, Equatable {
    let detail: String

    init(detail: String) {
        self.detail = detail
    }
}
